package chunking
import("bytes";"context";"errors";"testing")
func TestSplit(t *testing.T){for _,n:=range []int{0,1,15,16,17,256,1024*1024+3}{t.Run(string(rune(n+65)),func(t *testing.T){b:=make([]byte,n);for i:=range b{b[i]=byte(i%251)};var out []byte;h,size,e:=(Fixed{16}).Split(context.Background(),bytes.NewReader(b),func(c Chunk,p []byte)error{if c.Hash!=Hash(p)||c.Size!=int64(len(p)){t.Fatal("bad chunk")};out=append(out,p...);return nil});if e!=nil||h!=Hash(b)||size!=int64(n)||!bytes.Equal(b,out){t.Fatalf("split: %v",e)}})}}
func TestCancellationAndFailure(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel();_,_,e:=(Fixed{4}).Split(ctx,bytes.NewReader([]byte("hello")),func(Chunk,[]byte)error{return nil});if !errors.Is(e,context.Canceled){t.Fatal(e)};want:=errors.New("upload interrupted");_,_,e=(Fixed{4}).Split(context.Background(),bytes.NewReader([]byte("hello")),func(Chunk,[]byte)error{return want});if !errors.Is(e,want){t.Fatal(e)}}
func BenchmarkChunking(b *testing.B){data:=bytes.Repeat([]byte("vaultstore"),1<<20);b.SetBytes(int64(len(data)));b.ReportAllocs();for i:=0;i<b.N;i++{_,_,e:=(Fixed{4<<20}).Split(context.Background(),bytes.NewReader(data),func(Chunk,[]byte)error{return nil});if e!=nil{b.Fatal(e)}}}
